sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var body = request.body.data;

    // Basic validation
    if (!body || !body.hostname || !body.event_type) {
        response.setStatus(400);
        response.setBody({
            error: "Missing required fields: hostname and event_type are required."
        });
        return;
    }

    var validEventTypes = ['software_detected', 'hardware_status'];
    if (validEventTypes.indexOf(body.event_type) === -1) {
        response.setStatus(400);
        response.setBody({
            error: "Invalid event_type. Must be 'software_detected' or 'hardware_status'."
        });
        return;
    }

    try {
        var stage = new GlideRecord('x_1839598_automa_0_hardware_stage');
        stage.initialize();

        stage.setValue('hostname', body.hostname);
        stage.setValue('event_type', body.event_type);
        stage.setValue('ci_class', body.ci_class || '');
        stage.setValue('discovery_source', body.source || 'AALE_Simulated_Discovery');

        if (body.warranty_expiration) {
            stage.setValue('warranty_expiration', body.warranty_expiration);
        }
        if (body.lease_expiration) {
            stage.setValue('lease_expiration', body.lease_expiration);
        }
        if (body.detected_software) {
            stage.setValue('detected_software_json', JSON.stringify(body.detected_software));
        }
        if (body.scan_timestamp) {
            stage.setValue('scan_timestamp', body.scan_timestamp);
        }

        var sysId = stage.insert();

        if (!sysId) {
            response.setStatus(500);
            response.setBody({ error: "Failed to create Hardware Stage record." });
            return;
        }

        response.setStatus(201);
        response.setBody({
            status: "success",
            sys_id: sysId,
            message: "Hardware Stage record created."
        });

    } catch (e) {
        response.setStatus(500);
        response.setBody({ error: "Unexpected error: " + e.message });
    }

})(request, response);
